import{_ as s,o as e,c as i,a2 as t}from"./chunks/framework.DYPTBNgj.js";const k=JSON.parse('{"title":"Getting started","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/index.md","filePath":"getting-started/index.md","lastUpdated":1788977236000}'),n={name:"getting-started/index.md"};function o(l,a,h,d,r,p){return e(),i("div",null,[...a[0]||(a[0]=[t(`<h1 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting started&quot;">​</a></h1><p>This guide takes you from an installed package to a managed ZFS dataset. You do not need previous Boomerangz experience, but you should already have a working OpenZFS pool and know which dataset you want to protect.</p><h2 id="before-you-begin" tabindex="-1">Before you begin <a class="header-anchor" href="#before-you-begin" aria-label="Permalink to &quot;Before you begin&quot;">​</a></h2><p>You need:</p><ul><li>a platform listed as supported in the <a href="./installation">installation guide</a>;</li><li>OpenZFS and its <code>zfs</code> command-line tools;</li><li>administrative access for installing the package and delegating narrowly scoped ZFS permissions;</li><li>a source dataset that contains the data you want to protect;</li><li>enough space for retained snapshots and any local or remote copies.</li></ul><div class="warning custom-block"><p class="custom-block-title">Snapshots are not an independent backup</p><p>A snapshot shares the source pool&#39;s hardware. Configure replication to another pool or host if you need protection from loss of the source pool.</p></div><h2 id="_1-install-boomerangz" tabindex="-1">1. Install Boomerangz <a class="header-anchor" href="#_1-install-boomerangz" aria-label="Permalink to &quot;1. Install Boomerangz&quot;">​</a></h2><p>Follow the <a href="./installation">installation guide</a>. Leave the service stopped until you have delegated its ZFS access and checked the configuration.</p><h2 id="_2-delegate-access-to-the-source-dataset" tabindex="-1">2. Delegate access to the source dataset <a class="header-anchor" href="#_2-delegate-access-to-the-source-dataset" aria-label="Permalink to &quot;2. Delegate access to the source dataset&quot;">​</a></h2><p>Run this as a ZFS administrator on the source host, replacing <code>tank/data</code> with your dataset:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> zfs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> allow</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> boomerangz</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  bookmark,destroy,hold,mount,release,send,snapshot,userprop</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  tank/data</span></span></code></pre></div><p>The permission applies to the selected dataset and, according to normal OpenZFS delegation rules, its descendants. Select the narrowest suitable root. Do not give the service account unrestricted <code>sudo</code>.</p><h2 id="_3-review-and-validate-the-daemon-configuration" tabindex="-1">3. Review and validate the daemon configuration <a class="header-anchor" href="#_3-review-and-validate-the-daemon-configuration" aria-label="Permalink to &quot;3. Review and validate the daemon configuration&quot;">​</a></h2><p>The packaged defaults are safe for local use without a network listener:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudoedit</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/boomerangz/config.toml</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">boomerangz</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">boomerangz</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> show</span></span></code></pre></div><p>See <a href="/guide/configuration">Configure the daemon</a> before adding destinations or network access.</p><h2 id="_4-grant-local-control-access" tabindex="-1">4. Grant local control access <a class="header-anchor" href="#_4-grant-local-control-access" aria-label="Permalink to &quot;4. Grant local control access&quot;">​</a></h2><p>Add your administrative user to the <code>boomerangz</code> group so it can use the local status and control socket without running Boomerangz commands through <code>sudo</code>:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> usermod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --append</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --groups</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> boomerangz</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$USER</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span></code></pre></div><p>Sign out and back in for the new group membership to take effect. Membership grants access to all local control operations, so add only users who are trusted to administer the running daemon. See <a href="/guide/security#local-control-access">Local control access</a> for the socket permissions and security boundary.</p><h2 id="_5-enable-the-dataset" tabindex="-1">5. Enable the dataset <a class="header-anchor" href="#_5-enable-the-dataset" aria-label="Permalink to &quot;5. Enable the dataset&quot;">​</a></h2><p>If you enable a dataset without setting a policy, Boomerangz uses the default retention grid <code>12x5m,24x1h,14x1d</code>: 12 five-minute snapshots, 24 hourly snapshots, and 14 daily snapshots.</p><p>The following example replaces that default with an hourly cadence, keeping 24 hourly snapshots followed by 14 daily snapshots:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> zfs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> org.boomerangz:policy=24x1h,14x1d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tank/data</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> zfs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> org.boomerangz:enabled=on</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tank/data</span></span></code></pre></div><p>Settings are inherited by child datasets. Read <a href="/guide/datasets">Manage datasets</a> before enabling a parent that has children with different requirements.</p><h2 id="_6-start-the-daemon" tabindex="-1">6. Start the daemon <a class="header-anchor" href="#_6-start-the-daemon" aria-label="Permalink to &quot;6. Start the daemon&quot;">​</a></h2><div class="vp-code-group vp-adaptive-theme"><div class="tabs"><input type="radio" name="group-fAr53" id="tab-bBmXm_Y" checked><label data-title="Linux / systemd" for="tab-bBmXm_Y">Linux / systemd</label></div><div class="blocks"><div class="language-sh vp-adaptive-theme active"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enable</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --now</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> boomerangz.service</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> boomerangz.service</span></span></code></pre></div></div></div><h2 id="_7-confirm-operation" tabindex="-1">7. Confirm operation <a class="header-anchor" href="#_7-confirm-operation" aria-label="Permalink to &quot;7. Confirm operation&quot;">​</a></h2><p>Inspect the effective dataset policy, queue a snapshot immediately, and watch the result:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">boomerangz</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dataset</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> inspect</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tank/data</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">boomerangz</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> trigger</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tank/data</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">boomerangz</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --watch</span></span></code></pre></div><p>Check that a managed snapshot appears:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">zfs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> snapshot</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tank/data</span></span></code></pre></div><p>Next, configure a <a href="/guide/remotes">local or remote destination</a>. Until you do, the snapshots remain on the source pool only.</p>`,33)])])}const g=s(n,[["render",o]]);export{k as __pageData,g as default};
